import React, { useState } from 'react';
import { updateExamData } from '../services/api';
// import API from '../api';

const ExamData = () => {
  const [franchiseId, setFranchiseId] = useState('');
  const [formData, setFormData] = useState({
    examName: '',
    date: '',
    studentsAttended: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFranchiseChange = (e) => {
    setFranchiseId(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await updateExamData(formData);
      alert('Exam data updated successfully!');
      console.log('Response:', response.data); // Debugging: Log response
    } catch (error) {
      alert('Error updating exam data: ' + error.response?.data?.message || error.message);
      console.error('Error:', error); // Debugging: Log error
    }
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="franchiseId">Franchise ID:</label>
          <input
            id="franchiseId"
            name="franchiseId"
            placeholder="Enter Franchise ID"
            value={franchiseId}
            onChange={handleFranchiseChange}
            required
          />
        </div>
        <div>
          <label htmlFor="examName">Exam Name:</label>
          <input
            id="examName"
            name="examName"
            placeholder="Enter Exam Name"
            value={formData.examName}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="studentsAttended">Students Attended:</label>
          <input
            id="studentsAttended"
            name="studentsAttended"
            type="number"
            placeholder="Number of Students"
            value={formData.studentsAttended}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit">Update Exam Data</button>
      </form>
    </div>
  );
};

export default ExamData;
